import pathlib
from html.parser import HTMLParser

class SectionParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.ids=set()
        self.in_title=False
        self.title=''
    def handle_starttag(self, tag, attrs):
        if tag=='title':
            self.in_title=True
        for k,v in attrs:
            if k=='id' and v:
                self.ids.add(v)
    def handle_endtag(self, tag):
        if tag=='title':
            self.in_title=False
    def handle_data(self, data):
        if self.in_title:
            self.title += data

p=pathlib.Path('output/final_report.html')
html=p.read_text(encoding='utf-8')
parser=SectionParser()
parser.feed(html)
req={'station-utilization','queue-wait-analysis','energy-grid-load','renewable-pricing','vehicle-charging-behavior','optimization-recommendations'}
missing=sorted(req-parser.ids)
assert not missing, missing
assert parser.title.strip(), 'missing title'
print('OK: title and required section ids present; bytes', len(html.encode('utf-8')))
PY

